@sig trait Attention_Derivation_Api {
  def id: Art.BridgeId
  def decision_disposition_Id : Art.PortId
  def battery_assessment_Id : Art.PortId
  def attention_status_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var attention_status: Drone_Lifecycle_Governor.Attention_Status.Type = $

  def put_attention_status(value : Drone_Lifecycle_Governor.Attention_Status.Type) : Unit = {
    Contract(
      Modifies(attention_status),
      Ensures(
        attention_status == value
      )
    )
    Spec {
      attention_status = value
    }

    Art.putValue(attention_status_Id, Drone_Lifecycle_Governor.Attention_Status_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Attention_Derivation_Initialization_Api (
  val id: Art.BridgeId,
  val decision_disposition_Id : Art.PortId,
  val battery_assessment_Id : Art.PortId,
  val attention_status_Id : Art.PortId) extends Attention_Derivation_Api

